extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var script = load("res://advance_controller.gd")
	if not check("script_exists", script != null, "Lo script res://advance_controller.gd deve esistere"):
		return

	var ac = script.new()
	check("read_count_initial", ac.get_read_count() == 0, "get_read_count() inizialmente deve restituire 0")

	ac.mark_line_as_read("res://c1.json", 0)
	ac.mark_line_as_read("res://c1.json", 1)
	check("read_count_after", ac.get_read_count() == 2, "get_read_count() dopo 2 righe deve restituire 2 (restituito %d)" % ac.get_read_count())

	var delay_normal: float = ac.calculate_auto_delay("123456789012345678901234567890123456789012345678901234567890", 1.0)
	check("delay_normal", absf(delay_normal - 3.0) < 0.01, "calculate_auto_delay con 60 caratteri e speed 1.0 deve restituire 3.0 (restituito %.2f)" % delay_normal)

	var delay_fast: float = ac.calculate_auto_delay("123456789012345678901234567890123456789012345678901234567890", 2.0)
	check("delay_fast", absf(delay_fast - 1.5) < 0.01, "calculate_auto_delay con 60 caratteri e speed 2.0 deve restituire 1.5 (restituito %.2f)" % delay_fast)

	ac.reset_read_history()
	check("reset_history", ac.get_read_count() == 0, "reset_read_history() deve azzerare le righe lette")
	check("is_read_after_reset", ac.is_line_read("res://c1.json", 0) == false, "Dopo il reset la riga non deve più risultare letta")
	ac.free()

